function getCrop3DProfile(cropIdOrName = '') {
  if (!cropIdOrName) return crop3DProfiles['c-04'] || crop3DProfiles['c-01'];
  if (crop3DProfiles[cropIdOrName]) return crop3DProfiles[cropIdOrName];
  const q = String(cropIdOrName).toLowerCase().trim();
  if (crop3DProfiles[q]) return crop3DProfiles[q];

  // Explicit botanical keyword mappings (eliminates silent wheat fallthrough!)
  if (q.includes('banana') || q.includes('केला')) return crop3DProfiles['banana'];
  if (q.includes('rose') || q.includes('गुलाब')) return crop3DProfiles['rose'];
  if (q.includes('wheat') || q.includes('गेहूं') || q.includes('गहू')) return crop3DProfiles['wheat'];
  if (q.includes('rice') || q.includes('paddy') || q.includes('धान') || q.includes('भात')) return crop3DProfiles['rice'];
  if (q.includes('maize') || q.includes('corn') || q.includes('मक्का') || q.includes('मका')) return crop3DProfiles['maize'];
  if (q.includes('cotton') || q.includes('कपास')) return crop3DProfiles['cotton'];
  if (q.includes('tomato') || q.includes('टमाटर')) return crop3DProfiles['tomato'];
  if (q.includes('potato') || q.includes('आलू') || q.includes('बटाटा')) return crop3DProfiles['potato'];
  if (q.includes('chilli') || q.includes('pepper') || q.includes('मिर्च')) return crop3DProfiles['chilli'];

  for (const id in crop3DProfiles) {
    const p = crop3DProfiles[id];
    if (p.archetype === q) return p;
    if (p.name.toLowerCase() === q || p.name.toLowerCase().includes(q) || q.includes(p.name.toLowerCase().split(' ')[0])) {
      return p;
    }
  }

  // Fallback: Return explicit unsupported profile, NEVER silently substitute wheat!
  return {
    id: q,
    name: cropIdOrName,
    isUnsupported: true,
    category: "Unsupported Species",
    archetype: "unsupported_crop",
    heightScale: 1.0,
    fruitColor: "#f59e0b",
    hasWaterLayer: false
  };
}

