    desc: "Deccan / Vidarbha / Malwa region deep clay soil with moderate monsoon",
    farm: { acres: 8, season: 'Kharif', irrigation: 'Rainfed', previousCrop: 'Wheat' },
    soil: { type: 'Deep Black Vertisol', fertilityIndex: 72, n: 210, p: 38, k: 220, ph: 7.6, oc: 0.55, moisture: 36 },
