/**
 * 7. Real-Time Smart Crop Recommendation Predictor with XAI Reasoning
 */
function predictSmartCrop(input) {
  const { N = 90, P = 42, K = 43, temp = 25, humidity = 70, ph = 6.5, rainfall = 200, moisture = 45 } = input;

  // Real multi-variable distance & suitability scoring against agronomic baselines
  const crops = [
    {
      name: 'Rice',
      ideal: { N: 80, P: 40, K: 40, temp: 24, humidity: 80, ph: 6.5, rainfall: 220 },
      reasons: ['High rainfall requirement matched', 'Warm temperature optimal', 'Ideal NPK ratio']
    },
    {
      name: 'Maize',
      ideal: { N: 75, P: 45, K: 40, temp: 22, humidity: 65, ph: 6.2, rainfall: 90 },
      reasons: ['Moderate rainfall requirement', 'Balanced NPK nutrient profile', 'Optimal soil pH range']
    },
    {
      name: 'Wheat',
      ideal: { N: 50, P: 25, K: 30, temp: 18, humidity: 55, ph: 6.8, rainfall: 60 },
      reasons: ['Cooler temperature suited', 'Low moisture demand', 'Neutral soil pH']
    },
    {
      name: 'Cotton',
      ideal: { N: 120, P: 60, K: 50, temp: 28, humidity: 60, ph: 7.2, rainfall: 80 },
      reasons: ['High Nitrogen requirement', 'Warm climate preference', 'Slightly alkaline soil tolerance']
    },
    {
      name: 'Chickpea',
      ideal: { N: 40, P: 60, K: 80, temp: 20, humidity: 40, ph: 7.0, rainfall: 45 },
      reasons: ['Low Nitrogen requirement (legume)', 'High Potassium tolerance', 'Low water duty requirement']
    }
  ];

  const scoredCrops = crops.map(crop => {
    const id = crop.ideal;
    const distN = Math.pow((N - id.N) / 100, 2);
    const distP = Math.pow((P - id.P) / 60, 2);
    const distK = Math.pow((K - id.K) / 60, 2);
    const distTemp = Math.pow((temp - id.temp) / 20, 2);
    const distHum = Math.pow((humidity - id.humidity) / 50, 2);
    const distPh = Math.pow((ph - id.ph) / 2, 2);
    const distRain = Math.pow((rainfall - id.rainfall) / 150, 2);

    const totalDist = Math.sqrt(distN + distP + distK + distTemp + distHum + distPh + distRain);
    const confidence = Math.max(40, Math.min(99, Math.round(100 - totalDist * 32)));

    return {
      name: crop.name,
      confidence,
      reasons: crop.reasons
    };
  }).sort((a, b) => b.confidence - a.confidence);

  const primary = scoredCrops[0];
  const alternatives = scoredCrops.slice(1, 4);

  return {
    primaryCrop: primary.name,
    confidence: primary.confidence,
    alternatives,
    reasons: primary.reasons,
    inputSummary: { N, P, K, temp, humidity, ph, rainfall, moisture }
  };
}

