// Unified Plant Pathology Database: Combines core curated diseases with the 242 comprehensive diseases from expandedPlantDiseaseDatabase
const combinedDiseaseMap = new Map();
corePlantDiseaseDatabase.forEach(d => combinedDiseaseMap.set(d.id, d));
expandedPlantDiseaseDatabase.forEach(d => {
  if (!combinedDiseaseMap.has(d.id)) {
    combinedDiseaseMap.set(d.id, d);
  }
});
const plantDiseaseDatabase = exports.plantDiseaseDatabase = Array.from(combinedDiseaseMap.values());

