/**
 * Intelligent Fallback Generator for Disease Etiology & Outbreak Triggers
 */
function getFallbackWhyThisHappens(disease) {
  if (!disease) return null;
  const isHealthy = disease.pathogenType?.toLowerCase().includes('healthy');
  if (isHealthy) {
    return {
      pathogenCause: "Healthy physiological state. Plant leaf shows balanced chlorophyll synthesis, intact cellular cuticles, and strong natural systemic acquired resistance (SAR).",
      weatherTriggers: {
        temperature: "Favorable growth range (20°C - 32°C)",
        humidity: "Moderate relative humidity (50% - 70%) with good air circulation",
        leafWetness: "Leaves dry promptly in morning sun, preventing fungal spore incubation"
      },
      transmissionMode: "No transmission active. Maintained through clean seed, balanced organic nutrition, and sound soil biology.",
      riskFactors: [
        "Preventative monitoring remains key: sudden cloudy humid spells can trigger latent spores.",
        "Maintain balanced N-P-K fertilizer and avoid excessive chemical urea that softens leaf cell walls."
      ]
    };
  }

  const name = (disease.diseaseName || '').toLowerCase();

  if (name.includes('rust')) {
    return {
      pathogenCause: "Basidiomycete obligate biotrophic rust fungi (Puccinia species) producing microscopic orange-brown urediniospores that penetrate leaf stomata.",
      weatherTriggers: {
        temperature: "15°C - 24°C (Moderate cool-to-warm weather)",
        humidity: "High humidity (>85%) with persistent morning dew or light drizzling rain",
        leafWetness: "At least 3 - 6 hours of continuous leaf wetness needed for rust spores to germinate"
      },
      transmissionMode: "Airborne urediniospores travel hundreds of kilometers on continental wind currents. Once deposited, spores germinate within hours on damp leaves.",
      riskFactors: [
        "Dense crop canopy with stagnant air and prolonged dew.",
        "Excessive nitrogenous fertilizer creating tender leaf tissue susceptible to spore penetration.",
        "Late sowing dates exposing crops to peak sporulation seasons."
      ]
    };
  }

  if (name.includes('powdery') || name.includes('mildew')) {
    return {
      pathogenCause: "Ectophytic ascomycete fungus producing dense superficial white mycelial mats and asexual conidia chains on the upper leaf epidermis.",
      weatherTriggers: {
        temperature: "20°C - 28°C (Warm days followed by cool humid nights)",
        humidity: "High relative humidity (70% - 90%) at night; thrives even in the absence of free standing water",
        leafWetness: "Dry leaf surfaces during day allow spore release; night humidity promotes infection"
      },
      transmissionMode: "Microscopic conidiospores are easily dislodged by gentle wind breezes and farm workers, spreading rapidly throughout the orchard or field canopy.",
      riskFactors: [
        "Shady, overcrowded vine canopies or unpruned branches.",
        "Water stress combined with high humidity microclimates.",
        "High nitrogen fertilization and low potassium levels."
      ]
    };
  }

  if (name.includes('late blight') || name.includes('downy')) {
    return {
      pathogenCause: "Aggressive oomycete water mold (Phytophthora / Plasmopara) producing motile flagellated zoospores that swim through water films to breach leaf cuticle.",
      weatherTriggers: {
        temperature: "12°C - 22°C (Cool, damp, overcast conditions)",
        humidity: "Continuous relative humidity >90% or heavy sustained rainfall",
        leafWetness: "Leaves remain wet for over 6 hours under cloudy skies without bright sun"
      },
      transmissionMode: "Sporangia are carried by cool misty wind currents and splashed by raindrops. In water droplets, each sporangium bursts into 8-12 swimming zoospores.",
      riskFactors: [
        "Low-lying waterlogged patches in field.",
        "Overhead sprinkler irrigation during late evening or cloudy days.",
        "Using infected seed tubers or planting next to culled potato dumps."
      ]
    };
  }

  if (name.includes('curl') || name.includes('virus')) {
    return {
      pathogenCause: "Geminivirus / Begomovirus that hijacks plant cell nuclei, disrupting normal hormone synthesis, chlorophyll formation, and vascular transport.",
      weatherTriggers: {
        temperature: "26°C - 35°C (Warm, dry spells favor explosive insect vector breeding)",
        humidity: "Moderate humidity (50% - 65%) with sunny weather",
        leafWetness: "Not rain-dependent; infection occurs strictly via insect vector feeding"
      },
      transmissionMode: "Vectored primarily by the Silverleaf Whitefly (Bemisia tabaci) and aphids. A vector acquires the virus in 15-30 minutes of sap feeding and transmits it persistently to healthy plants.",
      riskFactors: [
        "Absence of insect barrier netting and lack of yellow sticky traps.",
        "Presence of weed hosts (e.g. Parthenium, Solanum nigrum) acting as viral reservoirs around field borders.",
        "High insecticide resistance in local whitefly populations due to indiscriminate spraying."
      ]
    };
  }

  return {
    pathogenCause: `Causal biological agent associated with ${disease.diseaseName || 'pathogen'}. Survives in soil, crop debris, or infected seeds.`,
    weatherTriggers: {
      temperature: "20°C - 30°C",
      humidity: "Relative humidity >75%",
      leafWetness: "Prolonged leaf wetness >4 hours"
    },
    transmissionMode: "Dispersed by rain splash, wind currents, and mechanical tools during field operations.",
    riskFactors: [
      "Overhead irrigation keeping leaves damp.",
      "Dense crop spacing restricting ventilation.",
      "Lack of crop rotation."
    ]
  };
}

/**
 * Retrieves the comprehensive etiology profile for a given disease ID
 */
function getWhyThisHappens(diseaseId, disease = null) {
  if (diseaseId && diseaseEtiologyDatabase[diseaseId]) {
    return diseaseEtiologyDatabase[diseaseId];
  }
  return getFallbackWhyThisHappens(disease);
}

