/**
 * Formats a cohesive, professional Plant Pathology Report
 */

function formatAnalysisResult(disease, confidence, biomarkers, topCandidates = [], fileName = '', isDemoSample = false, cropRecData = null, selectedCropHint = 'all') {
  const isHealthy = disease.isHealthy || disease.pathogenType === 'Healthy Foliage';
  const healthyRef = healthyCropReferenceModels[disease.cropKey] || healthyCropReferenceModels.tomato;

  const vernacularInfo = {
    commonName: disease.commonName || disease.diseaseName.split('(')[0].trim(),
    scientificName: disease.scientificName || '',
    vernacularName: disease.vernacularName || disease.diseaseName
  };

  const whyThisHappens = disease.whyThisHappens || getWhyThisHappens(disease.diseaseId || disease.id, disease);

  const effectiveCrop = (selectedCropHint && selectedCropHint !== 'all')
    ? selectedCropHint
    : (cropRecData ? cropRecData.cropKey : disease.cropKey);

  const regName = SUPPORTED_CROP_REGISTRY[effectiveCrop]?.name;
  const effectiveCropName = regName || (cropRecData && (!selectedCropHint || selectedCropHint === 'all') ? cropRecData.cropName : (disease.cropName || (effectiveCrop.charAt(0).toUpperCase() + effectiveCrop.slice(1))));

  const effectiveConfidence = (selectedCropHint && selectedCropHint !== 'all')
    ? Number(confidence.toFixed(1))
    : (cropRecData ? cropRecData.confidence : Number(confidence.toFixed(1)));

  const cropRecognition = {
    cropKey: effectiveCrop,
    cropName: effectiveCropName,
    confidence: effectiveConfidence,
    isReliable: cropRecData ? !cropRecData.isAmbiguous : true,
    isAmbiguous: cropRecData ? cropRecData.isAmbiguous : false,
    botanicalClass: healthyRef.botanicalClass,
    leafMorphology: healthyRef.leafMorphology,
    marginType: healthyRef.marginType,
    aspectRatioDescriptor: healthyRef.aspectRatioDescriptor,
    runnerUp: cropRecData?.runnerUp || (topCandidates[1] ? { cropKey: disease.cropKey, cropName: topCandidates[1].crop, confidence: topCandidates[1].prob } : null),
    topAlternatives: cropRecData?.topCandidates || [],
    diagnosticTelemetry: cropRecData?.diagnosticTelemetry || null
  };

  const healthyBaseline = {
    cropKey: healthyRef.cropKey,
    cropName: healthyRef.cropName,
    botanicalClass: healthyRef.botanicalClass,
    leafMorphology: healthyRef.leafMorphology,
    marginType: healthyRef.marginType,
    aspectRatioDescriptor: healthyRef.aspectRatioDescriptor,
    svg: healthyRef.svg,
    realPhotoUrl: healthyRef.realPhotoUrl,
    realPhotoDescription: healthyRef.realPhotoDescription,
    healthyBiomarkers: healthyRef.healthyBiomarkers,
    healthyTraits: healthyRef.healthyTraits,
    observedBiomarkers: biomarkers,
    deviationAnalysis: {
      greenDeficit: Math.max(0, (healthyRef.healthyBiomarkers?.green || 96) - biomarkers.greenPercentage),
      necroticSpread: biomarkers.necroticPercentage,
      chlorosisSpread: biomarkers.chlorosisPercentage,
      powderySpread: biomarkers.powderyPercentage,
      rustSpread: biomarkers.rustPercentage,
      pathogenSpread: biomarkers.necroticPercentage + biomarkers.chlorosisPercentage + biomarkers.powderyPercentage + biomarkers.rustPercentage,
      healthStatus: isHealthy ? 'Nominal (Healthy Baseline Foliage)' : 'Pathological Tissue Loss'
    }
  };

  return {
    isValidImage: true,
    id: disease.diseaseId || disease.id,
    crop: disease.cropName,
    cropKey: disease.cropKey,
    diseaseName: disease.diseaseName,
    commonName: vernacularInfo.commonName,
    scientificName: vernacularInfo.scientificName,
    vernacularName: vernacularInfo.vernacularName,
    pathogenType: disease.pathogenType,
    confidence: Number(confidence.toFixed(1)),
    severity: disease.severity || (isHealthy ? 'None (Healthy)' : 'Moderate'),
    cropRecognition,
    healthyBaseline,
    symptoms: disease.symptoms || [],
    whyThisHappens,
    culturalMeasures: disease.culturalMeasures || [],
    biologicalControl: disease.biologicalControl || [],
    chemicalControl: disease.chemicalControl || [],
    preventiveCare: disease.preventiveCare || [],
    recommendedActions: [
      ...(disease.culturalMeasures ? disease.culturalMeasures.slice(0, 1) : []),
      ...(disease.chemicalControl && disease.chemicalControl[0] ? ['Chemical: ' + disease.chemicalControl[0].chemical + ' @ ' + disease.chemicalControl[0].dosage] : []),
      ...(disease.biologicalControl ? disease.biologicalControl.slice(0, 1) : [])
    ],
    kvkHelpline: disease.kvkHelpline || 'National Kisan Call Center: 1800-180-1551 (ICAR)',
    biomarkers,
    boundingBox: null, // Authentic classification model does NOT invent bounding boxes
    topCandidates,
    fileName: fileName || null,
    isDemoSample: Boolean(isDemoSample),
    screeningMode: isDemoSample ? 'AgroSense Demo Specimen (MobileNet V1 Inference)' : 'AgroSense CV MobileNet V1 (Multi-Crop 56-Class Deep Learning)',
    disclaimer: 'AI computer vision screening advisory — please cross-verify with your local Krishi Vigyan Kendra (KVK) officer before large-scale chemical pesticide purchase.'
  };
}

/* Module Exports */
exports.analyzeLeafImage = analyzeLeafImage;
exports.formatAnalysisResult = formatAnalysisResult;
exports.loadPlantVillageModel = loadPlantVillageModel;
exports.initDiseaseModel = initDiseaseModel;
exports.getModelStatus = getModelStatus;
exports.subscribeModelStatus = subscribeModelStatus;
exports.MODEL_STATUS = MODEL_STATUS;
exports.runTensorFlowInference = runTensorFlowInference;
exports.SUPPORTED_CROP_REGISTRY = SUPPORTED_CROP_REGISTRY;
exports.PLANTVILLAGE_CLASSES = PLANTVILLAGE_CLASSES;
exports.getSampleDataUrl = getSampleDataUrl;
exports.validateLeafImage = validateLeafImage;
exports.getWhyThisHappens = getWhyThisHappens;
