  const avgTemp = (dataset.reduce((acc, r) => acc + (Number(r.Avg_Temperature_C) || 0), 0) / dataset.length || 0).toFixed(1);
  const avgMoisture = (dataset.reduce((acc, r) => acc + (Number(r['Soil_Moisture_%']) || 0), 0) / dataset.length || 0).toFixed(1);

  // Stats for selected FODS column
  const statsColVals = dataset.map(r => Number(r[filter.statsCol])).filter(v => !isNaN(v)).sort((a, b) => a - b);
  const n = statsColVals.length || 1;
  const meanVal = (statsColVals.reduce((a, b) => a + b, 0) / n).toFixed(2);
  const medianVal = (n % 2 === 0 ? (statsColVals[n / 2 - 1] + statsColVals[n / 2]) / 2 : statsColVals[Math.floor(n / 2)]).toFixed(2);
